test('invoiceTotals correctly calculates with tier discounts', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 10 },
      { sku: 'DEV-HOUR', qty: 5 },
    ],
  });
  assert.equal(result.ok, true);

  const totals = invoiceTotals(result.value);
  const line1Total = 10 * 8500; // 85000
  const line1Discount = line1Total * 5 / 100; // 4250
  const line1BaseAmount = line1Total - line1Discount; // 80750
  const line1Vat = Math.round(line1BaseAmount * 21 / 100); // 16958
  const line2Total = 5 * 9500; // 47500
  const line2Discount = line2Total * 5 / 100; // 2375
  const line2BaseAmount = line2Total - line2Discount; // 45125
  const line2Vat = Math.round(line2BaseAmount * 21 / 100); // 9476
  const expectedSubtotal = line1Total + line2Total; // 132500
  const expectedDiscount = line1Discount + line2Discount; // 6625
  const expectedVat = line1Vat + line2Vat; // 26434
  const expectedTotal = expectedSubtotal - expectedDiscount + expectedVat; // 152309

  assert.equal(totals.subtotal, expectedSubtotal);
  assert.equal(totals.discount, expectedDiscount);
  assert.equal(totals.vat, expectedVat);
  assert.equal(totals.total, expectedTotal);
});

