test('invoiceTotals integrates with createInvoice', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 10 },
      { sku: 'DEV-HOUR', qty: 5 },
    ],
  });
  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  const expectedSubtotal = 10 * 8500 + 5 * 9500; // 132500
  const expectedVat = Math.round(85000 * 21 / 100) + Math.round(47500 * 21 / 100); // 17850 + 9975 = 27825
  const expectedTotal = expectedSubtotal + expectedVat; // 160325
  assert.equal(totals.subtotal, expectedSubtotal);
  assert.equal(totals.vat, expectedVat);
  assert.equal(totals.total, expectedTotal);
});

test('addLine adds a new line to a draft invoice', () => {
