test('invoiceTotals includes discount and calculates total correctly', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 10, discountPercent: 10 },
      { sku: 'DEV-HOUR', qty: 5, discountPercent: 0 },
    ],
  });
  assert.equal(result.ok, true);

  const totals = invoiceTotals(result.value);
  const line1Total = 10 * 8500; // 85000
  const line1Discount = line1Total * 10 / 100; // 8500
  const line1BaseAmount = line1Total - line1Discount; // 76500
  const line1Vat = Math.round(line1BaseAmount * 21 / 100); // 16065
  const line2Total = 5 * 9500; // 47500
  const line2Vat = Math.round(line2Total * 21 / 100); // 9975
  const expectedSubtotal = line1Total + line2Total; // 132500
  const expectedDiscount = line1Discount; // 8500
  const expectedVat = line1Vat + line2Vat; // 26040
  const expectedTotal = expectedSubtotal - expectedDiscount + expectedVat; // 150040

  assert.equal(totals.subtotal, expectedSubtotal);
  assert.equal(totals.discount, expectedDiscount);
  assert.equal(totals.vat, expectedVat);
  assert.equal(totals.total, expectedTotal);
});

